    @Test
    fun forCharacter_visits_negative_ascii_and_default_branches() {
        // Negative -> int 0 entry.
        val neg = PostTableEntry.forCharacter(-1)
        assertTrue(neg.isInteger)
        assertEquals(0, neg.intValue())

        // ASCII range 0x20..0x7E -> ch - 29.
        for (ch in 0x20..0x7E) {
            val e = PostTableEntry.forCharacter(ch)
            assertTrue(e.isInteger)
            assertEquals(ch - 29, e.intValue())
        }

        // Default branch: code points outside the table -> "uniXXXX" or "uXXXXXX".
        val bmp = PostTableEntry.forCharacter(0xABCD)
        assertTrue(bmp.isString)
        assertEquals("uniABCD", bmp.stringValue())
        val sup = PostTableEntry.forCharacter(0x10001)
        assertTrue(sup.isString)
        assertEquals("u10001", sup.stringValue())
    }

    @Test
    fun forCharacter_sweeps_all_labelled_cases() {
        // Visit every labelled case so every `case 0xXXXX` line executes.
        for (cp in cps) {
            val e = PostTableEntry.forCharacter(cp)
            // Result must be either int or string and toString must be non-null.
            assertTrue(e.isInteger || e.isString)
            assertTrue(e.toString().isNotEmpty())
        }
    }

    @Test
    fun forCharacterName_sweeps_all_named_branches() {
        for (n in names) {
            val e = PostTableEntry.forCharacterName(n)
            assertTrue(e.isInteger || e.isString)
        }
        // Null and unknown name fall through.
        val nullE = PostTableEntry.forCharacterName(null)
        assertTrue(nullE.isInteger)
        assertEquals(0, nullE.intValue())
        val unknown = PostTableEntry.forCharacterName("totally-unknown-glyph")
        assertTrue(unknown.isString)
        assertEquals("totally-unknown-glyph", unknown.stringValue())
    }

    @Test
    fun postTableEntry_value_helpers_and_equality() {
        val intEntry = PostTableEntry(42)
        assertTrue(intEntry.isInteger)
        assertTrue(!intEntry.isString)
        assertEquals(42, intEntry.intValue())
        assertEquals("", intEntry.stringValue())
        assertEquals("42", intEntry.toString())

        val strEntry = PostTableEntry("foo")
        assertTrue(strEntry.isString)
        assertTrue(!strEntry.isInteger)
        assertEquals(0, strEntry.intValue())
        assertEquals("foo", strEntry.stringValue())
        assertEquals("foo", strEntry.toString())

        // equals
        assertTrue(intEntry.equals(intEntry))
        assertTrue(intEntry.equals(PostTableEntry(42)))
        assertTrue(!intEntry.equals(PostTableEntry(43)))
        assertTrue(strEntry.equals(PostTableEntry("foo")))
        assertTrue(!strEntry.equals(PostTableEntry("bar")))
        assertTrue(!intEntry.equals("not a PostTableEntry"))

        // hashCode paths.
        assertEquals(Integer.valueOf(42).hashCode(), intEntry.hashCode())
        assertEquals("foo".hashCode(), strEntry.hashCode())
    }
